import sys
import math

def main():
    N = int(sys.stdin.readline())

    d = 1
    while d * d * d <= N:
        disc = 12 * d * N - 3 * d**4
        if disc >= 0:
            s = math.isqrt(disc)
            if s * s == disc:
                num = s - 3 * d * d
                den = 6 * d
                if num > 0 and num % den == 0:
                    y = num // den
                    x = y + d
                    if x > 0 and y > 0 and x**3 - y**3 == N:
                        print(x, y)
                        return
        d += 1

    print(-1)

if __name__ == "__main__":
    main()
